#!/usr/bin/env node
// kar-glyphguard — Agensi skill script, generated by build.mjs in the sjgant80-hub/kar-glyphguard repository.
// The KERNEL block below is byte-identical to the logic of the live page (index.html) and to
// kernel.mjs, which the tests and the witness mutation gate run against. No network, no dependencies,
// writes no files: it reads the input you name and prints a JSON report to stdout.
// MIT licence.
// ---- KERNEL (from index.html) ----
/* ============================== CORE (pure, deterministic) ============================== */

var CONFUSABLES = {
  0x0410:['A','CYRILLIC CAPITAL LETTER A','Cyrillic'], 0x0412:['B','CYRILLIC CAPITAL LETTER VE','Cyrillic'],
  0x0415:['E','CYRILLIC CAPITAL LETTER IE','Cyrillic'], 0x041A:['K','CYRILLIC CAPITAL LETTER KA','Cyrillic'],
  0x041C:['M','CYRILLIC CAPITAL LETTER EM','Cyrillic'], 0x041D:['H','CYRILLIC CAPITAL LETTER EN','Cyrillic'],
  0x041E:['O','CYRILLIC CAPITAL LETTER O','Cyrillic'], 0x0420:['P','CYRILLIC CAPITAL LETTER ER','Cyrillic'],
  0x0421:['C','CYRILLIC CAPITAL LETTER ES','Cyrillic'], 0x0422:['T','CYRILLIC CAPITAL LETTER TE','Cyrillic'],
  0x0425:['X','CYRILLIC CAPITAL LETTER HA','Cyrillic'], 0x0405:['S','CYRILLIC CAPITAL LETTER DZE','Cyrillic'],
  0x0408:['J','CYRILLIC CAPITAL LETTER JE','Cyrillic'],
  0x0430:['a','CYRILLIC SMALL LETTER A','Cyrillic'], 0x0435:['e','CYRILLIC SMALL LETTER IE','Cyrillic'],
  0x043E:['o','CYRILLIC SMALL LETTER O','Cyrillic'], 0x0440:['p','CYRILLIC SMALL LETTER ER','Cyrillic'],
  0x0441:['c','CYRILLIC SMALL LETTER ES','Cyrillic'], 0x0443:['y','CYRILLIC SMALL LETTER U','Cyrillic'],
  0x0445:['x','CYRILLIC SMALL LETTER HA','Cyrillic'], 0x0455:['s','CYRILLIC SMALL LETTER DZE','Cyrillic'],
  0x0456:['i','CYRILLIC SMALL LETTER BYELORUSSIAN-UKRAINIAN I','Cyrillic'], 0x0458:['j','CYRILLIC SMALL LETTER JE','Cyrillic'],
  0x04CF:['l','CYRILLIC SMALL LETTER PALOCHKA','Cyrillic'],
  0x0391:['A','GREEK CAPITAL LETTER ALPHA','Greek'], 0x0392:['B','GREEK CAPITAL LETTER BETA','Greek'],
  0x0395:['E','GREEK CAPITAL LETTER EPSILON','Greek'], 0x0396:['Z','GREEK CAPITAL LETTER ZETA','Greek'],
  0x0397:['H','GREEK CAPITAL LETTER ETA','Greek'], 0x0399:['I','GREEK CAPITAL LETTER IOTA','Greek'],
  0x039A:['K','GREEK CAPITAL LETTER KAPPA','Greek'], 0x039C:['M','GREEK CAPITAL LETTER MU','Greek'],
  0x039D:['N','GREEK CAPITAL LETTER NU','Greek'], 0x039F:['O','GREEK CAPITAL LETTER OMICRON','Greek'],
  0x03A1:['P','GREEK CAPITAL LETTER RHO','Greek'], 0x03A4:['T','GREEK CAPITAL LETTER TAU','Greek'],
  0x03A5:['Y','GREEK CAPITAL LETTER UPSILON','Greek'], 0x03A7:['X','GREEK CAPITAL LETTER CHI','Greek'],
  0x03BF:['o','GREEK SMALL LETTER OMICRON','Greek'], 0x03BD:['v','GREEK SMALL LETTER NU','Greek'],
  0x03C1:['p','GREEK SMALL LETTER RHO','Greek'], 0x03C5:['u','GREEK SMALL LETTER UPSILON','Greek'],
  0x03B9:['i','GREEK SMALL LETTER IOTA','Greek'],
  0x2113:['l','SCRIPT SMALL L','Letterlike'], 0x0131:['i','LATIN SMALL LETTER DOTLESS I','Latin'],
  0x0130:['I','LATIN CAPITAL LETTER I WITH DOT ABOVE','Latin']
};

var INVISIBLE = {
  0x00AD:'SOFT HYPHEN', 0x034F:'COMBINING GRAPHEME JOINER', 0x180E:'MONGOLIAN VOWEL SEPARATOR',
  0x200B:'ZERO WIDTH SPACE', 0x200C:'ZERO WIDTH NON-JOINER', 0x200D:'ZERO WIDTH JOINER',
  0x2060:'WORD JOINER', 0x2061:'FUNCTION APPLICATION', 0x2062:'INVISIBLE TIMES',
  0x2063:'INVISIBLE SEPARATOR', 0x2064:'INVISIBLE PLUS', 0xFEFF:'ZERO WIDTH NO-BREAK SPACE / BOM'
};

var BIDI = {
  0x061C:'ARABIC LETTER MARK', 0x200E:'LEFT-TO-RIGHT MARK', 0x200F:'RIGHT-TO-LEFT MARK',
  0x202A:'LEFT-TO-RIGHT EMBEDDING', 0x202B:'RIGHT-TO-LEFT EMBEDDING', 0x202C:'POP DIRECTIONAL FORMATTING',
  0x202D:'LEFT-TO-RIGHT OVERRIDE', 0x202E:'RIGHT-TO-LEFT OVERRIDE',
  0x2066:'LEFT-TO-RIGHT ISOLATE', 0x2067:'RIGHT-TO-LEFT ISOLATE', 0x2068:'FIRST STRONG ISOLATE', 0x2069:'POP DIRECTIONAL ISOLATE'
};
var BIDI_HIGH_RISK = {0x202D:1, 0x202E:1};

// Mathematical Alphanumeric Symbols (U+1D400-1D7FF): contiguous 26/26/10 style runs.
// Each pair below is [A-Z run start, a-z run start] for one of the 13 Latin math styles in the block.
var MATH_STYLES = [
  [0x1D400,0x1D41A],[0x1D434,0x1D44E],[0x1D468,0x1D482],[0x1D49C,0x1D4B6],[0x1D4D0,0x1D4EA],
  [0x1D504,0x1D51E],[0x1D538,0x1D552],[0x1D56C,0x1D586],[0x1D5A0,0x1D5BA],[0x1D5D4,0x1D5EE],
  [0x1D608,0x1D622],[0x1D63C,0x1D656],[0x1D670,0x1D68A]
];
var MATH_DIGIT_STARTS = [0x1D7CE,0x1D7D8,0x1D7E2,0x1D7EC,0x1D7F6];

function decodeMathAlnum(cp){
  for (var i=0;i<MATH_STYLES.length;i++){
    var up = MATH_STYLES[i][0], lo = MATH_STYLES[i][1];
    if (cp>=up && cp<=up+25) return String.fromCharCode(65+(cp-up));
    if (cp>=lo && cp<=lo+25) return String.fromCharCode(97+(cp-lo));
  }
  for (var j=0;j<MATH_DIGIT_STARTS.length;j++){
    var d = MATH_DIGIT_STARTS[j];
    if (cp>=d && cp<=d+9) return String.fromCharCode(48+(cp-d));
  }
  return null;
}

function scriptOf(cp){
  if ((cp>=0x41&&cp<=0x5A)||(cp>=0x61&&cp<=0x7A)||(cp>=0x00C0&&cp<=0x024F)) return 'Latin';
  if (cp>=0x0400&&cp<=0x04FF) return 'Cyrillic';
  if (cp>=0x0370&&cp<=0x03FF) return 'Greek';
  if ((cp>=0x30&&cp<=0x39)||cp===0x20||/\s/.test(String.fromCodePoint(cp))) return 'Common';
  return 'Other';
}

var TAG_LO=0xE0020, TAG_HI=0xE007E, TAG_CANCEL=0xE007F;
function isVarSel(cp){ return (cp>=0xFE00&&cp<=0xFE0F)||(cp>=0xE0100&&cp<=0xE01EF); }
function isFullwidth(cp){ return cp>=0xFF01&&cp<=0xFF5E; }

function stableStringify(obj){
  if (obj===null||typeof obj!=='object') return JSON.stringify(obj);
  if (Array.isArray(obj)) return '['+obj.map(stableStringify).join(',')+']';
  var keys=Object.keys(obj).sort();
  return '{'+keys.map(function(k){ return JSON.stringify(k)+':'+stableStringify(obj[k]); }).join(',')+'}';
}

function cpHex(cp){ return 'U+' + cp.toString(16).toUpperCase().padStart(4,'0'); }

function scan(text){
  var cps = Array.from(text); // code-point aware, not UTF-16-unit aware
  var findings = [];
  var hiddenTagBuf = '';
  var hiddenSegments = [];
  var mathDecoded = '';
  var fullwidthDecoded = '';
  var counts = { confusable:0, invisible:0, bidi:0, hiddenTag:0, mathAlnum:0, fullwidth:0, variationSelector:0 };

  cps.forEach(function(ch, i){
    var cp = ch.codePointAt(0);
    var handled = false;

    if (cp>=TAG_LO && cp<=TAG_HI){
      hiddenTagBuf += String.fromCharCode(cp - 0xE0000);
      findings.push({pos:i, codepoint:cpHex(cp), char:'[tag]', category:'hidden-tag', severity:'high', detail:'Unicode tag character decodes to ASCII "'+String.fromCharCode(cp-0xE0000)+'" (invisible in normal rendering)'});
      counts.hiddenTag++; handled = true;
    } else if (cp === TAG_CANCEL){
      if (hiddenTagBuf) { hiddenSegments.push(hiddenTagBuf); hiddenTagBuf=''; }
      findings.push({pos:i, codepoint:cpHex(cp), char:'[tag-end]', category:'hidden-tag', severity:'high', detail:'Unicode CANCEL TAG (end of hidden tag sequence)'});
      counts.hiddenTag++; handled = true;
    }

    if (!handled && INVISIBLE[cp] !== undefined){
      findings.push({pos:i, codepoint:cpHex(cp), char:'[invisible]', category:'invisible', severity:'low', detail:INVISIBLE[cp]});
      counts.invisible++; handled = true;
    }

    if (!handled && BIDI[cp] !== undefined){
      var hi = !!BIDI_HIGH_RISK[cp];
      findings.push({pos:i, codepoint:cpHex(cp), char:'[bidi]', category:'bidi', severity: hi?'high':'medium', detail:BIDI[cp] + (hi ? ' (can visually reorder surrounding text - "Trojan Source" style risk)' : '')});
      counts.bidi++; handled = true;
    }

    if (!handled && CONFUSABLES[cp] !== undefined){
      var c = CONFUSABLES[cp], like=c[0], name=c[1], script=c[2];
      findings.push({pos:i, codepoint:cpHex(cp), char:ch, category:'confusable', severity:'medium', detail:name+' ('+script+') looks like Latin "'+like+'"'});
      counts.confusable++; handled = true;
    }

    if (!handled && isVarSel(cp)){
      findings.push({pos:i, codepoint:cpHex(cp), char:'[varsel]', category:'variation-selector', severity:'medium', detail:'Variation selector - can be used as a covert data channel; presence flagged, payload not decoded'});
      counts.variationSelector++; handled = true;
    }

    var mathCh = decodeMathAlnum(cp);
    if (mathCh !== null){
      findings.push({pos:i, codepoint:cpHex(cp), char:ch, category:'math-alnum', severity:'medium', detail:'Styled mathematical-alphanumeric character, decodes to plain "'+mathCh+'"'});
      counts.mathAlnum++; mathDecoded += mathCh; handled = true;
    } else {
      mathDecoded += ch;
    }

    if (isFullwidth(cp)){
      var asc = String.fromCharCode(cp-0xFEE0);
      findings.push({pos:i, codepoint:cpHex(cp), char:ch, category:'fullwidth', severity:'medium', detail:'Fullwidth form, decodes to plain "'+asc+'"'});
      counts.fullwidth++; fullwidthDecoded += asc; handled = true;
    } else if (mathCh === null) {
      fullwidthDecoded += ch;
    }
  });
  if (hiddenTagBuf) hiddenSegments.push(hiddenTagBuf);

  // Mixed-script token check: Latin combined with Cyrillic or Greek in the same whitespace-delimited token.
  var tokens = text.split(/\s+/).filter(Boolean);
  var mixedScriptTokens = [];
  tokens.forEach(function(tok){
    var scripts = {};
    Array.from(tok).forEach(function(ch){
      var s = scriptOf(ch.codePointAt(0));
      if (s !== 'Common') scripts[s]=1;
    });
    if (scripts.Latin && (scripts.Cyrillic || scripts.Greek)){
      var list = Object.keys(scripts).sort();
      mixedScriptTokens.push({token:tok, scripts:list});
    }
  });

  var nfc = text.normalize('NFC');
  var nfkc = text.normalize('NFKC');

  var anyFinding = findings.length > 0 || mixedScriptTokens.length > 0;
  var order = {high:3, medium:2, low:1};
  var highestSeverity = null;
  findings.forEach(function(f){ if (!highestSeverity || order[f.severity] > order[highestSeverity]) highestSeverity = f.severity; });
  if (mixedScriptTokens.length && (!highestSeverity || order.medium > order[highestSeverity])) highestSeverity = 'medium';

  return {
    inputLength: cps.length,
    counts: counts,
    findings: findings,
    hiddenTagText: hiddenSegments.length ? hiddenSegments : null,
    mathAlnumDecoded: counts.mathAlnum ? mathDecoded : null,
    fullwidthDecoded: counts.fullwidth ? fullwidthDecoded : null,
    mixedScriptTokens: mixedScriptTokens,
    normalization: {
      nfcChanged: nfc !== text,
      nfkcChanged: nfkc !== text,
      nfcResult: nfc !== text ? nfc : null,
      nfkcResult: nfkc !== text ? nfkc : null
    },
    verdict: { status: anyFinding ? 'flagged' : 'clean', highestSeverity: highestSeverity }
  };
}

function sha256Hex(str){
  var bytes = new TextEncoder().encode(str);
  return crypto.subtle.digest('SHA-256', bytes).then(function(digest){
    return Array.from(new Uint8Array(digest)).map(function(b){ return b.toString(16).padStart(2,'0'); }).join('');
  });
}

// The export the page offers: the report plus the SHA-256 of the input text and of the canonical report.
function makeReport(text){
  var report = scan(text);
  return Promise.all([sha256Hex(text), sha256Hex(stableStringify(report))]).then(function(hs){
    return { tool:'glyphguard', version:'1.0.0', inputHash:hs[0], reportHash:hs[1], report:report };
  });
}

// Re-run the scan on the text and compare with a pasted export: content, input hash, report hash.
function verifyExport(text, exported){
  if (!exported || typeof exported !== 'object' || !exported.report){
    return Promise.resolve({ ok:false, notAnExport:true, contentMatches:false, inputHashMatches:null, reportHashSelfConsistent:null });
  }
  var recomputedCanon = stableStringify(scan(text));
  var contentMatches = recomputedCanon === stableStringify(exported.report);
  return Promise.all([sha256Hex(text), sha256Hex(recomputedCanon)]).then(function(hs){
    var inputHashMatches = exported.inputHash ? (hs[0] === exported.inputHash) : null;
    var reportHashSelfConsistent = exported.reportHash ? (hs[1] === exported.reportHash) : null;
    return {
      ok: contentMatches && inputHashMatches !== false && reportHashSelfConsistent !== false,
      notAnExport: false,
      contentMatches: contentMatches,
      inputHashMatches: inputHashMatches,
      reportHashSelfConsistent: reportHashSelfConsistent
    };
  });
}
// ---- CLI (from cli.mjs) ----
// cli.mjs — Glyphguard on the command line. build.mjs bundles this with the KERNEL block of index.html into
// scripts/kar-glyphguard.mjs, the single file the Agensi skill runs. It scans text for the tricks that hide in
// characters (invisible characters, homoglyphs, bidi overrides, hidden Unicode-tag text, styled or fullwidth
// letters, variation selectors, mixed-script words) and prints a hashed report; or re-verifies a report.
// The report is written as pure ASCII: every non-ASCII character is a \u escape, so the report itself can
// never carry a hidden character into whatever reads it.
// Exit 0 = clean (or the report verified) · 1 = flagged (or it did not verify) · 2 = unusable input.
import { readFileSync } from 'node:fs';

const USAGE = `usage: node kar-glyphguard.mjs --file <path>         scan a text file as it is (or - for stdin)
       node kar-glyphguard.mjs <input.json | ->          input: {"text": "…"}
       node kar-glyphguard.mjs <input.json | ->          input: {"text": "…", "export": {…a report this tool printed…}}
                                                          re-runs the scan and checks the report and its hashes
output: a JSON report on stdout, ASCII only. exit 0 = clean / verified, 1 = flagged / not verified, 2 = bad input`;

class InputError extends Error {}
const fail = (msg) => { throw new InputError(msg); };

function readText(path) {
  try { return readFileSync(path === '-' ? 0 : path, 'utf8'); }
  catch (e) { return fail(`cannot read ${path === '-' ? 'stdin' : path}: ${e.code || e.message}`); }
}

function asciiJson(value) {
  return JSON.stringify(value, null, 2).replace(/[\u007f-\uFFFF]/g, (c) => '\\u' + c.charCodeAt(0).toString(16).padStart(4, '0'));
}

async function main(args) {
  let text, exported;
  if (args.length === 2 && args[0] === '--file') {
    text = readText(args[1]);
  } else if (args.length === 1 && (args[0] === '-' || !args[0].startsWith('-'))) {
    let input;
    try { input = JSON.parse(readText(args[0])); } catch (e) { if (e instanceof InputError) throw e; fail(`the input is not valid JSON (${e.message})`); }
    if (!input || typeof input !== 'object' || typeof input.text !== 'string') fail('the input must be an object with "text" (a string)');
    text = input.text;
    if ('export' in input) exported = input.export;
  } else {
    process.stderr.write(USAGE + '\n');
    return 2;
  }
  if (exported !== undefined) {
    const v = await verifyExport(text, exported);
    process.stdout.write(asciiJson({ tool: 'kar-glyphguard', mode: 'verify', verdict: v.ok ? 'VERIFIED' : 'MISMATCH', ...v }) + '\n');
    return v.ok ? 0 : 1;
  }
  const exp = await makeReport(text);
  process.stdout.write(asciiJson(exp) + '\n');
  return exp.report.verdict.status === 'clean' ? 0 : 1;
}

try {
  process.exitCode = await main(process.argv.slice(2));
} catch (e) {
  process.stderr.write(`kar-glyphguard: ${e instanceof InputError ? e.message : 'internal error: ' + (e && e.message)}\n`);
  process.exitCode = e instanceof InputError ? 2 : 3;
}
